"""Check: draft with new terms swapped in, against the rails file. Lines that still differ need a look."""
import re,sys
D='english/pi-6-english-plain-zeroshot_split_chapters/';R='english/pi-6-english-plain-rails_split_chapters/'
SW=[('states of misery','§MISERY§'),('attainment of cessation','§AOC§'),('in arising and cessation','in arising and ending'),('arising and cessation','arising and ending'),('in cessation','in ending'),('on cessation','on ending'),('form or formless','fine-material or formless'),('form and formless','fine-material and formless'),('the sense sphere','the sense-pleasure element'),('the form sphere','the material-form element'),('the formless sphere','the immaterial element'),('In the form sphere','In the material-form element'),('In the formless sphere','In the immaterial element'),('form sphere','material-form element'),('formless sphere','immaterial element'),('the spheres','the elements'),('Spheres','Elements'),('In the sense-pleasure element','In the sense-pleasure element'),
('aggregate of material form','aggregate of form'),('aggregate of mental formations','aggregate of formations'),('mental formations','formations'),('beings without perception','non-percipient beings'),('those being reborn among non-percipient beings','those being reborn as non-percipient beings'),('final Nibbāna','final nibbāna'),('A worthy one (arahant)','An arahant'),('a worthy one','an arahant'),('A worthy one','An arahant'),('worthy ones','arahants'),('the Worthy One','the Arahant'),
('mental-object','mind-object'),('visible-form','visible-form'),('touch base','tangible base'),('the touch element','the tangible element'),('sense bases','bases'),('a sense base','a base'),('Sense Bases','Bases'),('form realm','fine-material sphere'),('sense realm','sense sphere'),('formless realm','formless sphere'),('neutral','indeterminate'),('Neutral','Indeterminate'),('wholesome states','wholesome phenomena'),('Wholesome states','Wholesome phenomena'),('Wholesome States','Wholesome Phenomena'),('indeterminate states','indeterminate phenomena'),('Indeterminate states','Indeterminate phenomena'),('Indeterminate States','Indeterminate Phenomena'),('mental states','mental phenomena'),('Mental States','Mental Phenomena'),('remaining states','remaining phenomena'),('a state','a phenomenon'),('any other state','any other phenomenon'),('states','phenomena'),('the distress faculty','the faculty of displeasure'),('distress','displeasure'),('the faculty of "I shall know the unknown"','the faculty "I shall know what is yet unknown"'),('"I shall know the unknown"','"I shall know what is yet unknown"'),('thought and examination','thought and holding the thought'),('in- and out-breathing','in-and-out breathing'),('A worthy one','An arahant'),('Truth of Cessation','Truth of the Ending'),('truth of cessation','truth of the ending'),('the origin','the origin'),('develop','cultivate'),('Cessation','Ending'),('remaining people','remaining persons'),('ordinary people','ordinary persons'),('Ordinary people','Ordinary persons'),('touch','the tangible')]
def norm(l):
    for a,b in SW: l=l.replace(a,b)
    return l.replace('cessation','ending').replace('§MISERY§','states of misery').replace('§AOC§','attainment of cessation')
SHOW=int(sys.argv[1])
for f in sys.argv[2:]:
    a=open(D+f,encoding='utf-8').read().split('\n');b=open(R+f,encoding='utf-8').read().split('\n')
    df=[(i+1,x,y) for i,(x,y) in enumerate(zip(a,b)) if norm(x)!=y]
    print(f,'differs',len(df),'of',len(a))
    for i,x,y in df[:SHOW]: print(' ',i,'D:',norm(x)[:170]);print(' ',i,'R:',y[:170])
